using System;
using WoWProbe;
class QuickCombatTests
{
    static int passed,failed;
    static void Test(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex.Message);}}
    static void Check(bool condition){if(!condition)throw new Exception("Unexpected combat behavior");}
    static FarmObservation Observation(){return new FarmObservation{TargetPositionKnown=true,TargetX=.3203,TargetY=.4703,Health=100,Fresh=true,KnownCore=true,MapId=1432,MapMode=1,Zone="TEST",X=.32,Y=.47,Facing=1,CastingKnown=true,TargetExists=true,TargetIdentityKnown=true,TargetToken=123,TargetName="怪物",NameHashKnown=true,TargetNameHash=1,AttackabilityKnown=true,TargetCanAttack=true,TargetDeadKnown=true,TargetReaction=4};}
    static QuickCommand Step(QuickCombat e,FarmObservation o,long time){o.Sequence++;return e.Step(o,time);}
    static QuickCombat Hunter(FarmObservation o,QuickHunterState state=null,bool ranged=false)
    {return new QuickCombat(o,750,false,null,"4563","4563",80,0,false,null,ranged,true,state);}
    static int Main()
    {
        Test("game too far feedback rolls back failed hunter key and forbids repeats until movement and range agree",()=>{
            var o=Observation();o.ActionRangeKnownMask=o.ActionsInRangeMask=63;
            var e=new QuickCombat(o,750,false,null,"56","3",80,0,false,null,true,true);Step(e,o,0);Step(e,o,40);
            var c=Step(e,o,100);Check(c.Key==53);e.HunterInputCompleted(c);
            o.RangeErrorActive=true;c=Step(e,o,200);Check(c.Action==QuickAction.Face&&c.AllowApproach&&c.Reason.Contains("距离太远"));
            for(int t=300;t<=2700;t+=100){if(t==2300)o.RangeErrorActive=false;Check(Step(e,o,t).Action!=QuickAction.Skill);}
            o.X+=.0002;Check(Step(e,o,2800).Action==QuickAction.RangedStop);c=Step(e,o,2900);Check(c.Key==53);e.HunterInputCompleted(c);
            Step(e,o,3600);c=Step(e,o,3700);Check(c.Key==54);o.RangeErrorActive=true;Check(!QuickCombat.Matches(c,o));
            o.InCombat=o.TargetVictimKnown=o.TargetTargetsPlayer=true;Step(e,o,3800);c=Step(e,o,3900);Check(c.Key==49&&c.HunterDefense);
        });
        Test("hunter resurrection waits for full recovery then acknowledges one aspect key across engines",()=>{
            var o=Observation();o.PlayerGhost=true;var state=new QuickHunterState();state.Observe(o);o.PlayerGhost=false;o.Health=30;o.FoodCount=10;
            var e=Hunter(o,state);Check(Step(e,o,0).Action==QuickAction.Food);e.RestInputCompleted(1500,true);
            o.Health=100;Check(Step(e,o,11000).Action==QuickAction.None&&e.IsResting);Check(Step(e,o,11500).Action==QuickAction.None&&!e.IsResting);
            var buff=Step(e,o,11600);Check(buff.Action==QuickAction.HunterAspect&&buff.Key==56&&QuickCombat.Matches(buff,o));
            o.Health=99;Check(!QuickCombat.Matches(buff,o));o.Health=100;o.InCombat=true;Check(!QuickCombat.Matches(buff,o));o.InCombat=false;
            e=Hunter(o,state);Check(Step(e,o,0).Action==QuickAction.HunterAspect);e.HunterInputCompleted(buff);Check(!e.HunterRecoveryPending&&Step(e,o,100).Action!=QuickAction.HunterAspect);
            o.PlayerDead=true;state.Observe(o);Check(state.AspectPending);
        });
        Test("hunter disabled and ordinary startup never issue post resurrection aspect",()=>{
            var o=Observation();var state=new QuickHunterState();Check(Step(Hunter(o,state),o,0).Action!=QuickAction.HunterAspect);
            o.PlayerDead=true;state.Observe(o);o.PlayerDead=false;var e=new QuickCombat(o,750,false,null,"","2",80,0,false,null,false,false,state);
            Check(!e.HunterRecoveryPending&&Step(e,o,0).Action!=QuickAction.HunterAspect);
        });
        Test("hunter under direct attack skips all remaining opening keys and cycles one two",()=>{
            foreach(bool ranged in new[]{false,true}){
                var o=Observation();o.ActionRangeKnownMask=o.ActionsInRangeMask=63;var e=Hunter(o,null,ranged);Step(e,o,0);Step(e,o,40);
                var first=Step(e,o,100);Check(first.Key==52);e.HunterInputCompleted(first);
                o.InCombat=o.TargetVictimKnown=o.TargetTargetsPlayer=true;Check(Step(e,o,200).Report);
                var keys="";for(int t=300;t<4500;t+=100){var c=Step(e,o,t);if(c.Action==QuickAction.Skill){Check(c.HunterDefense&&QuickCombat.Matches(c,o));keys+=(char)c.Key;e.HunterInputCompleted(c);}}
                Check(keys.StartsWith("1212"));Check(keys.IndexOf('4')<0&&keys.IndexOf('5')<0&&keys.IndexOf('6')<0&&keys.IndexOf('3')<0);
            }
        });
        Test("hunter drops unissued opening on health loss and does not confuse pet combat with self attack",()=>{
            var o=Observation();o.ActionRangeKnownMask=o.ActionsInRangeMask=63;o.InCombat=o.TargetVictimKnown=true;var e=Hunter(o);Step(e,o,0);Step(e,o,40);var c=Step(e,o,100);Check(c.Key==52&&!c.HunterDefense);
            o.TargetVictimKnown=false;o.Health=95;Check(!QuickCombat.Matches(c,o));Check(Step(e,o,200).Report);c=Step(e,o,300);Check(c.Key==49&&c.HunterDefense);
            o.Casting=true;Check(Step(e,o,400).Action==QuickAction.InterruptSkin);
        });
        Test("hunter checks each current skill range without skipping five six three or advancing a cancelled input",()=>{
            var o=Observation();o.ActionRangeKnownMask=63;o.ActionsInRangeMask=8;var e=Hunter(o);Step(e,o,0);Step(e,o,40);
            var c=Step(e,o,100);Check(c.Key==52);e.HunterInputCompleted(c);
            long t=200;
            foreach(char key in "563"){
                c=Step(e,o,t);Check(c.Action==QuickAction.Face&&c.AllowApproach);
                c=Step(e,o,t+200);Check(c.Action==QuickAction.None);
                int bit=1<<(key-'1');o.ActionsInRangeMask|=bit;Check(Step(e,o,t+300).Action==QuickAction.RangedStop);
                c=Step(e,o,t+1000);Check(c.HunterSkill&&c.Key==key&&QuickCombat.Matches(c,o));
                o.ActionsInRangeMask&=~bit;Check(!QuickCombat.Matches(c,o));o.ActionsInRangeMask|=bit;
                e.HunterInputCompleted(c);t+=1100;
            }
        });
        Test("hunter unreadable required range holds the same skill and incoming attack replaces it",()=>{
            var o=Observation();var e=new QuickCombat(o,750,false,null,"5","5",80,0,false,null,false,true);Step(e,o,0);Check(Step(e,o,100).Action==QuickAction.None);
            o.InCombat=o.TargetVictimKnown=o.TargetTargetsPlayer=true;Step(e,o,200);var c=Step(e,o,300);Check(c.Key==49&&c.HunterDefense);
        });
        Test("contact cancels a queued combat detour before any turn or forward escape",()=>{for(int kind=0;kind<2;kind++){var o=Observation();o.InCombat=o.CastEventsKnown=o.MeleeEventsKnown=true;var e=new QuickCombat(o,750,false,null,"","2");Step(e,o,0);Step(e,o,40);Check(Step(e,o,3500).Action==QuickAction.BackOff);if(kind==0){o.MeleeHitToken=o.TargetToken;o.MeleeHits++;}else{o.TargetVictimKnown=o.TargetTargetsPlayer=true;o.Health=97;}bool skill=false;for(int t=3600;t<5000;t+=100){var c=Step(e,o,t);Check(c.Action!=QuickAction.BackOff&&c.Action!=QuickAction.DetourTurn&&c.Action!=QuickAction.DetourForward);if(c.Action==QuickAction.Skill)skill=true;}Check(skill);}});
        Test("interact binding alone never authorizes an assumed forward direction",()=>{var o=Observation();o.TargetPositionKnown=false;var e=new QuickCombat(o,750);Step(e,o,0);Check(Step(e,o,40).Action==QuickAction.Face);for(int t=500;t<=4000;t+=500){var c=Step(e,o,t);Check(c.Key!=QuickMovement.Forward);}Check(Step(e,o,4500).Action==QuickAction.Stop);});
        Test("a configured skill cooling down is not treated as a facing obstruction",()=>{var o=Observation();o.InCombat=o.CastEventsKnown=true;o.KnownActionsMask=o.UsableActionsMask=2;var e=new QuickCombat(o,750,false,null,"","2");Step(e,o,0);for(int t=500;t<=12000;t+=500){var c=Step(e,o,t);Check(c.Action!=QuickAction.BackOff&&c.Action!=QuickAction.DetourTurn&&c.Action!=QuickAction.DetourForward);}});
        Test("ranged target outside shooting range approaches then stops at range and never toggles active auto shot",()=>{var o=Observation();o.RangedActionsMask=4;o.MeleeActionsMask=3;o.ActionRangeKnownMask=6;o.RepeatKnownMask=15;o.KnownActionsMask=o.ReadyActionsMask=o.UsableActionsMask=7;var e=new QuickCombat(o,750,false,null,"","3121212",80,0,false,null,true);Step(e,o,0);var face=Step(e,o,40);Check(face.Action==QuickAction.Face&&face.AllowApproach);Check(Step(e,o,500).Action==QuickAction.None);o.ActionsInRangeMask=4;Check(Step(e,o,600).Action==QuickAction.RangedStop);var shot=Step(e,o,700);Check(shot.Action==QuickAction.Skill&&shot.Key==51&&QuickCombat.Matches(shot,o));o.RepeatingMask=4;Check(!QuickCombat.Matches(shot,o));for(int t=800;t<=2500;t+=100){var c=Step(e,o,t);Check(c.Action!=QuickAction.Skill&&c.Action!=QuickAction.Face);}o.ActionsInRangeMask=0;face=Step(e,o,2600);Check(face.Action==QuickAction.Face&&face.AllowApproach);});
        Test("ranged defender uses in-range melee backup instead of continuing into shooting dead zone",()=>{var o=Observation();o.RangedActionsMask=4;o.MeleeActionsMask=3;o.ActionRangeKnownMask=6;o.ActionsInRangeMask=2;o.InCombat=true;var e=new QuickCombat(o,750,false,null,"","312",80,0,false,null,true);Step(e,o,0);var face=Step(e,o,40);Check(face.Action==QuickAction.Face&&!face.AllowApproach);var c=Step(e,o,100);Check(c.Action==QuickAction.Skill&&c.Key==49);Check(Step(e,o,850).Key==50);});
        Test("ranged unavailable action is skipped and last-moment cooldown or range changes cancel input",()=>{var o=Observation();o.RangedActionsMask=4;o.ActionRangeKnownMask=o.ActionsInRangeMask=4;o.KnownActionsMask=o.ReadyActionsMask=4;var e=new QuickCombat(o,750,false,null,"","3",80,0,false,null,true);Step(e,o,0);Step(e,o,40);Check(Step(e,o,100).Action==QuickAction.None);o.UsableActionsMask=4;var c=Step(e,o,850);Check(c.Action==QuickAction.Skill&&QuickCombat.Matches(c,o));o.ReadyActionsMask=0;Check(!QuickCombat.Matches(c,o));o.ReadyActionsMask=4;o.ActionsInRangeMask=0;Check(!QuickCombat.Matches(c,o));});
        Test("ranged mode starts configured skills without melee evidence and keeps target guards",()=>{var o=Observation();o.MeleeEventsKnown=true;var e=new QuickCombat(o,750,false,null,"","312",80,0,false,null,true);Step(e,o,0);Check(Step(e,o,40).Action==QuickAction.Face);var c=Step(e,o,350);Check(c.Action==QuickAction.Skill&&c.Key==51&&c.RangedSkill&&QuickCombat.Matches(c,o));o.TargetToken++;Check(!QuickCombat.Matches(c,o));o.TargetToken--;o.TargetIsPlayer=true;Check(!QuickCombat.Matches(c,o));o.TargetIsPlayer=false;o.TargetDead=true;Check(!QuickCombat.Matches(c,o));o.TargetDead=false;Check(Step(e,o,1100).Key==49);Check(Step(e,o,1850).Key==50);for(int t=2000;t<=9000;t+=100){c=Step(e,o,t);Check(c.Action!=QuickAction.Face&&c.Action!=QuickAction.BackOff&&c.Action!=QuickAction.DetourTurn);}Check(e.Kills==0);});
        Test("ranged skills four and five do not insert rogue builder two",()=>{var o=Observation();o.MeleeEventsKnown=o.CastEventsKnown=true;var e=new QuickCombat(o,750,false,null,"","45",80,0,false,null,true);Step(e,o,0);Step(e,o,40);Check(Step(e,o,100).Key==52);o.CastFailed++;Check(Step(e,o,850).Key==53);Check(Step(e,o,1600).Key==52);});
        Test("ranged food recovery never sends stealth Q and still waits ten seconds",()=>{var o=Observation();o.Health=50;var e=new QuickCombat(o,750,false,null,"","3",80,0,false,null,true);Check(Step(e,o,0).Action==QuickAction.Food);e.RestInputCompleted(100,true);Check(Step(e,o,200).Action==QuickAction.None);o.Health=100;Check(Step(e,o,10000).Action==QuickAction.None&&e.IsResting);Check(Step(e,o,10100).Action==QuickAction.None&&!e.IsResting);});
        Test("rogue food toggles Q once after actual food input and once at full health",()=>{var o=Observation();o.PowerType=3;o.Health=50;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Food);e.RestInputCompleted(100,true);Check(Step(e,o,200).Action==QuickAction.StealthEnter);o.Health=99;Check(Step(e,o,10000).Action==QuickAction.None);o.Health=100;Check(Step(e,o,10100).Action==QuickAction.StealthExit);Check(Step(e,o,10200).Action!=QuickAction.StealthExit);});
        Test("melee nonrogue food never presses Q or moves and holds ten seconds from actual input",()=>{
            foreach(int powerType in new[]{0,1,2,255}){
                var o=Observation();o.PowerType=powerType;o.Power=100;o.Health=25;o.FoodCount=10;
                var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Food);e.RestInputCompleted(1500,true);
                for(int t=1600;t<=11400;t+=200){o.Health=100;var c=Step(e,o,t);Check(c.Action==QuickAction.None&&c.Key==0&&e.IsResting&&!e.IsStealthRecovery);}
                o.Health=99;Check(Step(e,o,11500).Action==QuickAction.None&&e.IsResting);
                o.Health=100;Check(Step(e,o,11600).Action==QuickAction.None&&!e.IsResting);Step(e,o,11700);Check(Step(e,o,11800).Action==QuickAction.Face);
            }
        });
        Test("melee mana food and water finish without stealth and combat still interrupts recovery",()=>{
            var o=Observation();o.PowerType=0;o.Power=40;o.Health=25;o.FoodCount=10;
            var e=new QuickCombat(o,750,false,null,"","2",80,189);Check(Step(e,o,0).Action==QuickAction.Food);e.RestInputCompleted(1500,true);
            Check(Step(e,o,1600).Action==QuickAction.Drink);e.RestInputCompleted(1700);o.Health=100;o.Power=99;
            Check(Step(e,o,11600).Action==QuickAction.None&&e.IsResting);Check(Step(e,o,11700).Action==QuickAction.None&&!e.IsResting);
            o.Health=25;e=new QuickCombat(o,750);Step(e,o,0);e.RestInputCompleted(1500,true);o.InCombat=true;
            Check(Step(e,o,1600).Action!=QuickAction.Food&&!e.IsResting);Check(Step(e,o,1700).Action==QuickAction.Face);
        });
        Test("failed vanish resumes configured skills immediately without six second attack pause",()=>{var o=Observation();o.PowerType=3;o.Power=100;o.InCombat=true;o.Health=14;o.CastEventsKnown=o.RangeKnown=o.TargetInRange=true;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Vanish);o.CastFailed++;bool skill=false;for(int t=100;t<=1500;t+=100){var c=Step(e,o,t);Check(c.Action!=QuickAction.Vanish&&c.Action!=QuickAction.Food);if(c.Action==QuickAction.Skill)skill=true;}Check(skill);});
        Test("vanish recovery never eats and remains stationary until full health then Q",()=>{var o=Observation();o.InCombat=true;o.PowerType=3;o.Health=14;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Vanish);o.InCombat=false;Check(Step(e,o,1000).Action==QuickAction.StealthHold);for(int t=2000;t<90000;t+=1000)Check(Step(e,o,t).Action==QuickAction.None);o.Health=100;var c=Step(e,o,90000);Check(c.Action==QuickAction.StealthExit&&c.Key==81);});
        Test("failed vanish does not spam key six or eat in combat and fifteen percent does not trigger",()=>{var o=Observation();o.InCombat=true;o.PowerType=3;o.Health=15;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action!=QuickAction.Vanish);o.Health=14;Check(Step(e,o,100).Action==QuickAction.Vanish);for(long t=200;t<12000;t+=200){var c=Step(e,o,t);Check(c.Action!=QuickAction.Vanish&&c.Action!=QuickAction.Food);}});
        Test("rest preparation waits beyond delayed movement and rejects combat or frozen frames",()=>{var o=Observation();o.ChatOpenKnown=true;int elapsed=0;QuickRestPreparation.Wait(()=>o,ms=>{elapsed+=ms;o.Sequence++;if(elapsed<=500)o.X+=.0001;});Check(elapsed>=1500);foreach(bool combat in new[]{false,true}){elapsed=0;o=Observation();o.ChatOpenKnown=true;bool rejected=false;try{QuickRestPreparation.Wait(()=>o,ms=>{elapsed+=ms;if(combat){o.Sequence++;o.InCombat=true;}});}catch(InvalidOperationException){rejected=true;}Check(rejected);}});
        Test("food holds ten seconds even at full health and waits beyond ten seconds below full",()=>{var o=Observation();o.Health=50;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Food);o.Health=100;Check(Step(e,o,9999).Action==QuickAction.None&&e.IsResting);o.Health=99;Check(Step(e,o,10000).Action==QuickAction.None&&e.IsResting);o.Health=100;Check(Step(e,o,10100).Action==QuickAction.None&&!e.IsResting);});
        Test("repeated switches to unrelated corpses in combat rescan without stopping or kill credit",()=>{var o=Observation();o.InCombat=true;var e=new QuickCombat(o,750);long t=0;for(int i=0;i<6;i++){o.TargetToken=123;o.TargetDead=false;Step(e,o,t+=400);o.TargetToken=456;o.TargetDead=true;o.Health=9;Check(Step(e,o,t+=400).Action==QuickAction.Scan);Check(e.Kills==0);}});
        Test("failed armor finisher retries its own key after builder without skipping configured sequence",()=>{foreach(bool loop in new[]{false,true}){var o=Observation();o.CastEventsKnown=true;o.RangeKnown=o.TargetInRange=true;var e=new QuickCombat(o,750,false,null,loop?"":"53",loop?"5":"2");var keys=new System.Collections.Generic.List<ushort>();for(long t=0;t<10000&&keys.Count<5;t+=100){var c=Step(e,o,t);if(c.Action!=QuickAction.Skill)continue;keys.Add(c.Key);if(keys.Count==3||keys.Count==4)o.CastSuccess++;}Check(keys.Count==5&&keys[0]==53&&keys[1]==50&&keys[2]==50&&keys[3]==53&&keys[4]==(loop?53:51));}});
        Test("failed slice alternates to builder and waits for builder success without advancing opening",()=>{var o=Observation();o.CastEventsKnown=true;o.RangeKnown=o.TargetInRange=true;var e=new QuickCombat(o,750,false,null,"43","2");var keys=new System.Collections.Generic.List<ushort>();for(long t=0;t<10000&&keys.Count<5;t+=100){var c=Step(e,o,t);if(c.Action!=QuickAction.Skill)continue;keys.Add(c.Key);if(keys.Count==1)o.CastFailed++;if(keys.Count==3||keys.Count==4)o.CastSuccess++;}Check(keys.Count==5&&keys[0]==52&&keys[1]==50&&keys[2]==50&&keys[3]==52&&keys[4]==51);});
        Test("loop slice uses builder fallback too",()=>{var o=Observation();o.CastEventsKnown=true;o.RangeKnown=o.TargetInRange=true;var e=new QuickCombat(o,750,false,null,"","4");var keys=new System.Collections.Generic.List<ushort>();for(long t=0;t<8000&&keys.Count<4;t+=100){var c=Step(e,o,t);if(c.Action!=QuickAction.Skill)continue;keys.Add(c.Key);if(keys.Count==2||keys.Count==3)o.CastSuccess++;}Check(keys.Count==4&&keys[0]==52&&keys[1]==50&&keys[2]==52&&keys[3]==52);});
        Test("dead target with no victim retains corpse through combat lag and half second settling",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.InCombat=true;o.TargetDead=true;o.TargetCanAttack=false;o.TargetVictimKnown=true;o.TargetTargetsPlayer=false;Check(Step(e,o,100).Action==QuickAction.None);Check(Step(e,o,200).Action==QuickAction.None&&e.Kills==1);o.InCombat=false;Check(Step(e,o,300).Action==QuickAction.None);Check(Step(e,o,799).Action==QuickAction.None);Check(Step(e,o,800).Action==QuickAction.Loot&&e.Kills==1);});
        Test("food retries automatically after no recovery but does not spam while health rises or food runs out",()=>{var o=Observation();o.Health=50;o.FoodCount=4;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Food);Check(Step(e,o,5900).Action==QuickAction.None);Check(Step(e,o,10000).Action==QuickAction.Food);o.Health=60;Check(Step(e,o,11000).Action==QuickAction.None);Check(Step(e,o,15000).Action==QuickAction.None);Check(Step(e,o,21000).Action==QuickAction.Food);o.FoodCount=0;Check(Step(e,o,24000).Action==QuickAction.None);o.InCombat=true;Check(Step(e,o,25000).Action!=QuickAction.Food);});
        Test("attacked with no target scans immediately and does not reacquire old quarry",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.InCombat=true;o.TargetExists=false;var a=Step(e,o,100);if(a.Action!=QuickAction.Scan)throw new Exception("no target: "+a.Action+" "+a.Reason);o.TargetExists=true;o.TargetVictimKnown=true;o.TargetTargetsPlayer=false;var b=Step(e,o,500);if(b.Action!=QuickAction.Scan)throw new Exception("wrong target: "+b.Action+" "+b.Reason);o.TargetTargetsPlayer=true;Check(Step(e,o,600).Action==QuickAction.None);Check(Step(e,o,700).Action==QuickAction.Face);});
        Test("missing swing events use verified attacker and actual health loss to unlock configured skills",()=>{var o=Observation();o.MeleeEventsKnown=true;var e=new QuickCombat(o,750,false,null,"42","3");Step(e,o,0);Step(e,o,40);o.InCombat=true;o.Health=97;Check(Step(e,o,400).Action==QuickAction.None);o.TargetVictimKnown=true;o.TargetTargetsPlayer=true;Check(Step(e,o,500).Report);var skill=Step(e,o,600);Check(skill.Action==QuickAction.Skill&&skill.Key==52&&QuickCombat.Matches(skill,o));});
        Test("only a new player melee hit on locked target unlocks configured skills with unknown range",()=>{var o=Observation();o.MeleeEventsKnown=true;o.MeleeHits=9;o.MeleeHitToken=o.TargetToken;var e=new QuickCombat(o,750,false,null,"43","2");Step(e,o,0);Step(e,o,40);Check(Step(e,o,400).Action==QuickAction.None);o.MeleeHits++;o.MeleeHitToken=999;Check(Step(e,o,500).Action==QuickAction.None);o.MeleeHitToken=o.TargetToken;var skill=Step(e,o,600);Check(skill.Action==QuickAction.Skill&&skill.Key==52&&QuickCombat.Matches(skill,o));o.TargetToken++;Check(!QuickCombat.Matches(skill,o));});
        Test("unknown and distant range preserve opening until close; failed opening is retried",()=>{var o=Observation();o.CastEventsKnown=true;var e=new QuickCombat(o,750);Step(e,o,0);Check(Step(e,o,40).Action==QuickAction.Face);Check(Step(e,o,350).Action==QuickAction.None);o.RangeKnown=true;Check(Step(e,o,400).Action==QuickAction.None);o.TargetInRange=true;Check(Step(e,o,450).Key==50);Check(Step(e,o,1200).Key==50);o.CastSuccess++;Step(e,o,1600);Check(Step(e,o,2000).Key==52);});
        Test("pending facing and skills reject target swaps players and death",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);var c=Step(e,o,40);Check(QuickCombat.Matches(c,o));o.TargetToken=124;Check(!QuickCombat.Matches(c,o));o.TargetToken=123;o.TargetIsPlayer=true;Check(!QuickCombat.Matches(c,o));o.TargetIsPlayer=false;o.TargetDead=true;Check(!QuickCombat.Matches(c,o));});
        Test("only two distinct dead frames confirm a kill and permit loot",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.TargetDead=true;o.TargetCanAttack=false;Check(Step(e,o,100).Action==QuickAction.None&&e.Kills==0);Check(e.Step(o,140).Action==QuickAction.None&&e.Kills==0);Check(Step(e,o,200).Action==QuickAction.None&&e.Kills==1);Check(Step(e,o,699).Action==QuickAction.None);var loot=Step(e,o,700);Check(loot.Action==QuickAction.Loot&&e.Kills==1&&QuickCombat.Matches(loot,o));Check(Step(e,o,740).Action==QuickAction.None&&e.Kills==1);});
        Test("target disappearance requests one reselect then rescans without guessing a kill",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.TargetExists=false;Check(Step(e,o,100).Action==QuickAction.Reacquire&&e.Kills==0);Check(Step(e,o,800).Action==QuickAction.None&&e.Kills==0);Check(Step(e,o,2700).Action==QuickAction.None&&e.Kills==0);Check(Step(e,o,2900).Action==QuickAction.Scan&&e.Kills==0);});
        Test("stale stream death changed map and runaway distance stop even duplicate packets",()=>{for(int i=0;i<4;i++){var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);if(i==0)o.Fresh=false;if(i==1)o.PlayerDead=true;if(i==2)o.MapId++;if(i==3)o.X+=.041;Check(e.Step(o,100).Action==QuickAction.Stop);}});
        Test("45 second no-kill deadline stops repeated packets",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);Check(e.Step(o,45000).Action==QuickAction.Stop);});
        Test("unknown position or failed API cannot arm or continue input",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.ReadFailures=1;Check(Step(e,o,100).Action==QuickAction.Stop);o=Observation();e=new QuickCombat(o,750);o.X=Double.NaN;Check(Step(e,o,0).Action==QuickAction.Stop);});
        Test("low resurrection health rests before selecting an already visible mob",()=>{var o=Observation();o.Health=50;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Food);o.Health=90;Check(Step(e,o,1000).Action==QuickAction.None);o.Health=100;Check(Step(e,o,2000).Action==QuickAction.None);Check(Step(e,o,2200).Action==QuickAction.None);Check(Step(e,o,2400).Action==QuickAction.None);Check(Step(e,o,10000).Action==QuickAction.None);Check(Step(e,o,10200).Action==QuickAction.None);Check(Step(e,o,10400).Action==QuickAction.Face);});
        Test("unknown health cannot bypass the recovery gate",()=>{var o=Observation();o.Health=255;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Stop);});
        Test("energy below eighty is not a reason to drink",()=>{var o=Observation();o.PowerType=3;o.Power=10;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.None);Check(Step(e,o,200).Action==QuickAction.Face);});
        Test("combat may precede target telemetry without permanently stopping",()=>{var o=Observation();o.InCombat=true;o.TargetExists=false;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Scan);o.TargetExists=true;Check(Step(e,o,200).Action==QuickAction.None);Check(Step(e,o,400).Action==QuickAction.Face);});
        Test("a new encounter resets the missing combat target deadline",()=>{var o=Observation();o.InCombat=true;o.TargetExists=false;var e=new QuickCombat(o,750);Step(e,o,0);o.TargetExists=true;Step(e,o,200);o.TargetDead=true;Step(e,o,1000);Step(e,o,1200);Step(e,o,4000);o.TargetExists=false;Check(Step(e,o,4200).Action!=QuickAction.Stop);});
        Test("only neutral NPCs may start a fight while hostile attackers can be defended against",()=>{foreach(int reaction in new[]{3,4,5,255}){var o=Observation();o.TargetReaction=reaction;var e=new QuickCombat(o,750);Step(e,o,0);var c=Step(e,o,100);Check((c.Action==QuickAction.Face)==(reaction==4));}var attacked=Observation();attacked.InCombat=true;attacked.TargetReaction=3;var fight=new QuickCombat(attacked,750);Step(fight,attacked,0);Check(Step(fight,attacked,100).Action==QuickAction.Face);});
        Test("skipped hostile targets do not block bounded patrol movement",()=>{var o=Observation();o.TargetReaction=3;var e=new QuickCombat(o,750);Step(e,o,0);Step(e,o,1500);Step(e,o,3000);var c=Step(e,o,4500);Check(c.Action==QuickAction.Patrol&&QuickCombat.Matches(c,o));o.TargetReaction=4;Check(!QuickCombat.Matches(c,o));});
        Test("missing attacker selection allows one slow chat command but still has a six second bound",()=>{var o=Observation();o.InCombat=true;o.TargetExists=false;var e=new QuickCombat(o,750);Step(e,o,0);Check(Step(e,o,2600).Action!=QuickAction.Stop);Check(Step(e,o,6100).Action==QuickAction.Stop);});
        Test("roadside non skinnable loot works with skinning disabled",()=>{var o=Observation();o.InCombat=false;o.TargetDead=true;o.TargetCanAttack=false;o.LootKnown=o.Lootable=o.LootEventsKnown=true;o.SkinKnown=true;o.Skinnable=false;var e=new QuickCombat(o,750,false);Check(Step(e,o,0).Action==QuickAction.None);var c=Step(e,o,500);Check(c.Action==QuickAction.CorpseApproach&&QuickCombat.Matches(c,o));Check(Step(e,o,1600).Action==QuickAction.Loot);o.LootOpened=o.LootClosed=1;Step(e,o,2300);Check(e.Loots==1&&e.Skins==0&&e.Kills==0);});
        Test("latched death of the locked unit survives clearing and requests the same corpse",()=>{var o=Observation();o.DeathEventsKnown=true;o.TargetDeaths=4;var e=new QuickCombat(o,750);Step(e,o,0);o.TargetExists=false;o.DeathToken=123;o.TargetDeaths=5;Check(Step(e,o,200).Action==QuickAction.None&&e.Kills==0);Check(Step(e,o,400).Action==QuickAction.None&&e.Kills==1);Check(Step(e,o,900).Action==QuickAction.CorpseSelect);Step(e,o,1000);Check(e.Kills==1);});
        Test("old or unrelated death evidence cannot confirm the locked mob",()=>{for(int i=0;i<2;i++){var o=Observation();o.DeathEventsKnown=true;o.DeathToken=123;o.TargetDeaths=4;var e=new QuickCombat(o,750);Step(e,o,0);o.TargetExists=false;if(i==1){o.TargetDeaths=5;o.DeathToken=999;}Check(Step(e,o,200).Action==QuickAction.Reacquire&&e.Kills==0);Check(Step(e,o,2800).Action==QuickAction.None&&e.Kills==0);}});
        Test("stationary approach backs up turns and takes a bounded detour before facing again",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);Check(Step(e,o,4500).Action==QuickAction.BackOff);Check(Step(e,o,4800).Action==QuickAction.DetourTurn);o.Facing+=.6;Check(Step(e,o,5100).Action==QuickAction.DetourForward);Check(Step(e,o,5800).Action==QuickAction.Face);Check(Step(e,o,9600).Action==QuickAction.BackOff);Step(e,o,9900);o.Facing+=.6;Step(e,o,10200);Check(Step(e,o,14700).Action==QuickAction.Stop);});
        Test("failed mouse turn never authorizes forward movement and stops after bounded observation",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);Step(e,o,4500);Check(Step(e,o,4800).Action==QuickAction.DetourTurn);Check(Step(e,o,5100).Action==QuickAction.None);Check(Step(e,o,7700).Action==QuickAction.None);Check(Step(e,o,7800).Action==QuickAction.Stop);});
        Test("position or successful casts reset the stuck timer and combat prevents detours",()=>{for(int i=0;i<3;i++){var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);if(i==0)o.X+=.001;if(i==1){o.CastEventsKnown=true;o.CastSuccess++;}if(i==2)o.InCombat=true;Check(Step(e,o,4500).Action!=QuickAction.BackOff);}});
        Test("detours reject changed targets or combat before movement",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);var c=Step(e,o,4500);Check(QuickCombat.Matches(c,o));o.InCombat=true;Check(!QuickCombat.Matches(c,o));o.InCombat=false;o.TargetToken++;Check(!QuickCombat.Matches(c,o));});
        Test("unconfigured water waits for natural mana without pressing a substitute key",()=>{var o=Observation();o.PowerType=0;o.Power=50;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.None);var wait=Step(e,o,61000);Check(wait.Action==QuickAction.None&&wait.Key==0&&e.IsResting);o.Power=99;Check(Step(e,o,62000).Action==QuickAction.None&&!e.IsResting);});
        Test("returning to the already confirmed corpse reselects without crediting the next living mob",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.TargetDead=true;Step(e,o,100);Step(e,o,300);Check(e.Kills==1);o.LootEventsKnown=o.LootKnown=true;o.LootOpened=o.LootClosed=1;Step(e,o,1000);Step(e,o,2000);o.TargetToken=124;o.TargetDead=false;Step(e,o,2200);o.TargetToken=123;o.TargetDead=true;Check(Step(e,o,2300).Action==QuickAction.None&&e.Kills==1);o.TargetToken=124;o.TargetDead=false;Step(e,o,2600);Check(Step(e,o,2800).Action==QuickAction.Face);o.TargetDead=true;Step(e,o,3000);Step(e,o,3200);Check(e.Kills==2);});
        Test("reselect of the same dead identity confirms a kill and different identities never authorize attacks",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);o.TargetExists=false;var c=Step(e,o,100);Check(QuickCombat.Matches(c,o));o.TargetExists=true;o.TargetDead=true;Check(QuickCombat.Matches(c,o));Step(e,o,700);Step(e,o,900);Check(e.Kills==1);o.TargetToken=999;Check(!QuickCombat.Matches(c,o));});
        Test("empty scans can patrol but cancel movement for combat or a newly found mob",()=>{var o=Observation();o.TargetExists=false;var e=new QuickCombat(o,750);Step(e,o,0);Step(e,o,1500);Step(e,o,3000);var c=Step(e,o,4500);Check(c.Action==QuickAction.Patrol&&c.Hold==1000&&QuickCombat.Matches(c,o));o.InCombat=true;Check(!QuickCombat.Matches(c,o));o.InCombat=false;o.TargetExists=true;Check(!QuickCombat.Matches(c,o));});
        Test("low rogue health attempts evasion once then keeps fighting",()=>{var o=Observation();o.InCombat=true;o.PowerType=3;o.Health=40;var e=new QuickCombat(o,750);Step(e,o,0);var c=Step(e,o,200);Check(c.Action==QuickAction.Defensive&&c.Key==57);Check(Step(e,o,400).Action==QuickAction.Face);});
        Test("open chat stops normal combat and blocks pending skill keys",()=>{var o=Observation();var e=new QuickCombat(o,750);Step(e,o,0);var c=Step(e,o,200);o.ChatOpenKnown=o.ChatOpen=true;Check(!QuickCombat.Matches(c,o));Check(Step(e,o,400).Action==QuickAction.Stop);});
        Test("new first person XP credit confirms only the locked full monster name",()=>{for(int i=0;i<3;i++){var o=Observation();o.KillCreditsKnown=true;o.KillCredits=5;var e=new QuickCombat(o,750);Step(e,o,0);o.TargetExists=false;o.KillCredits=i==2?5u:6u;o.KillCreditNameHash=i==1?999u:1u;Step(e,o,200);Step(e,o,400);Check(e.Kills==(i==0?1:0));}});
        Test("empty food supply still acquires and attacks a mob when healthy",()=>{var o=Observation();o.FoodCount=0;o.MeleeEventsKnown=true;var e=new QuickCombat(o,750,false,null,"","3",80,0,false,null,true);Check(Step(e,o,0).Action==QuickAction.None);Check(Step(e,o,40).Action==QuickAction.Face);var c=Step(e,o,200);Check(c.Action==QuickAction.Skill&&c.Key==51&&QuickCombat.Matches(c,o));});
        Test("the final food item restores health then permits the next mob",()=>{var o=Observation();o.Health=50;o.FoodCount=1;var e=new QuickCombat(o,750);Check(Step(e,o,0).Action==QuickAction.Food);o.FoodCount=0;o.Health=80;Check(Step(e,o,1000).Action==QuickAction.None);o.Health=100;Check(Step(e,o,2000).Action==QuickAction.None);Check(Step(e,o,10000).Action==QuickAction.None);Check(Step(e,o,10200).Action==QuickAction.None);Check(Step(e,o,10400).Action==QuickAction.Face);});
        Test("no food and no water wait beyond one minute without item keys and resume at full",()=>{var o=Observation();o.FoodCount=0;o.Health=40;o.PowerType=0;o.Power=30;var e=new QuickCombat(o,750,false,null,"","3",80,0,false,null,true);var c=Step(e,o,0);Check(c.Action==QuickAction.None&&c.Report&&e.IsResting);Check(!Step(e,o,1000).Report);Check(Step(e,o,30000).Report);o.Health=80;o.Power=90;Check(Step(e,o,61000).Action==QuickAction.None&&e.IsResting);o.Health=99;o.Power=99;Check(Step(e,o,120000).Action==QuickAction.None&&e.IsResting);o.Health=100;Check(Step(e,o,130000).Action==QuickAction.None&&!e.IsResting);Step(e,o,130100);Check(Step(e,o,130200).Action==QuickAction.Face);Check(Step(e,o,130400).Action==QuickAction.Skill);});
        Test("attacks interrupt natural recovery and unknown health remains rejected",()=>{var o=Observation();o.FoodCount=0;o.Health=40;var e=new QuickCombat(o,750,false,null,"","3",80,0,false,null,true);Step(e,o,0);o.InCombat=true;Check(Step(e,o,100).Action!=QuickAction.Stop&&!e.IsResting);Check(Step(e,o,200).Action==QuickAction.Face);Check(Step(e,o,400).Action==QuickAction.Skill);o.Health=255;Check(Step(e,o,600).Action==QuickAction.Stop);});
        Test("productive searching keeps heading for twenty walks instead of cycling quarter turns",()=>{var o=Observation();o.TargetExists=false;var e=new QuickCombat(o,750);int walks=0;for(int i=0;i<40;i++){var c=Step(e,o,i*1500);Check(c.Action!=QuickAction.Turn&&c.Action!=QuickAction.Stop);if(c.Action==QuickAction.Patrol){walks++;o.Y+=.0008;}}Check(walks==20);});
        Test("search turns only after two failed walks and never walks before observing the turn",()=>{var o=Observation();o.TargetExists=false;var e=new QuickCombat(o,750);Step(e,o,0);Step(e,o,1500);Step(e,o,3000);Step(e,o,4500);var c=Step(e,o,6000);Check(c.Action==QuickAction.Turn&&c.MouseTurn);Check(Step(e,o,6200).Action==QuickAction.None);Check(Step(e,o,9000).Action==QuickAction.Stop);});
        Test("interrupted skin discards original corpse and blocks all corpses for sixty seconds",()=>{var o=Observation();o.LootKnown=true;o.Lootable=false;o.SkinKnown=o.Skinnable=o.SkinBindingKnown=o.SkinBindingCorrect=o.SkinSuccessKnown=o.CastEventsKnown=true;var e=new QuickCombat(o,750,true);Step(e,o,0);o.TargetDead=true;o.TargetCanAttack=false;Step(e,o,100);Step(e,o,200);Check(Step(e,o,700).Action==QuickAction.Skin);o.InCombat=true;o.Casting=true;Check(Step(e,o,800).Action==QuickAction.InterruptSkin);o.Casting=false;Step(e,o,900);o.InCombat=false;o.TargetToken=999;for(long t=1000;t<60800;t+=100){var c=e.Step(o,t);Check(c.Action!=QuickAction.Skin&&c.Action!=QuickAction.Loot&&c.Action!=QuickAction.CorpseSelect&&c.Action!=QuickAction.CorpseApproach);}Check(Step(e,o,60800).Action==QuickAction.None);Check(Step(e,o,61300).Action==QuickAction.CorpseApproach);});
        Test("custom opening loop and arbitrary manual interval drive skill attempts in order",()=>{var o=Observation();o.RangeKnown=o.TargetInRange=true;o.InCombat=true;var e=new QuickCombat(o,600,false,null,"2 4","35");Step(e,o,0);var keys=new System.Text.StringBuilder();long previous=-1000;for(long t=100;t<6000;t+=100){var c=Step(e,o,t);if(c.Action==QuickAction.Skill){Check(t-previous>=600);previous=t;keys.Append((char)c.Key);}}Check(keys.Length>=8&&keys.ToString().StartsWith("24353535"));bool rejected=false;try{new QuickCombat(o,600,false,null,"24","/run");}catch(FormatException){rejected=true;}Check(rejected);});
        Test("a new attacker interrupts our skin cast before returning to combat",()=>{var o=Observation();o.LootKnown=true;o.Lootable=false;o.SkinKnown=o.Skinnable=o.SkinBindingKnown=o.SkinBindingCorrect=o.SkinSuccessKnown=o.CastEventsKnown=true;var e=new QuickCombat(o,750,true);Step(e,o,0);o.TargetDead=true;o.TargetCanAttack=false;Step(e,o,100);Step(e,o,200);Check(Step(e,o,700).Action==QuickAction.Skin);o.Casting=true;o.InCombat=true;o.TargetToken=124;o.TargetDead=false;o.TargetCanAttack=true;var stop=Step(e,o,800);Check(stop.Action==QuickAction.InterruptSkin&&stop.Key==27&&QuickCombat.Matches(stop,o));o.Casting=false;Check(!QuickCombat.Matches(stop,o));Check(Step(e,o,900).Action==QuickAction.Scan);Step(e,o,1000);Check(Step(e,o,1100).Action==QuickAction.Face);});
        Test("claimed or already fighting mobs are skipped while actual self defense remains allowed",()=>{for(int i=0;i<2;i++){var o=Observation();if(i==0)o.TargetClaimKnown=o.TargetClaimedByOther=true;else{o.TargetCombatKnown=o.TargetInCombat=o.TargetVictimKnown=true;}var e=new QuickCombat(o,750);Step(e,o,0);Check(Step(e,o,100).Action!=QuickAction.Face);o.InCombat=true;o.TargetVictimKnown=o.TargetTargetsPlayer=true;Step(e,o,200);Check(Step(e,o,300).Action==QuickAction.Face);}var target=Observation();var engine=new QuickCombat(target,750);Step(engine,target,0);var c=Step(engine,target,100);target.TargetClaimKnown=target.TargetClaimedByOther=true;Check(!QuickCombat.Matches(c,target));});
        Test("configured water restores mana before acquiring a mob while rogues never drink",()=>{var o=Observation();o.PowerType=0;o.Power=50;o.FoodCount=10;var e=new QuickCombat(o,750,false,null,"24","2",80,53);var drink=Step(e,o,0);Check(drink.Action==QuickAction.Drink&&drink.Key==53);o.Power=90;Check(Step(e,o,1000).Action==QuickAction.None);o.Power=99;Step(e,o,10000);Step(e,o,10100);Check(Step(e,o,10200).Action==QuickAction.Face);o=Observation();o.PowerType=3;o.Power=0;e=new QuickCombat(o,750,false,null,"24","2",80,53);Check(Step(e,o,0).Action==QuickAction.None);Check(Step(e,o,100).Action==QuickAction.Face);});
        Test("manual recovery threshold and attacks during recovery retain combat priority",()=>{var o=Observation();o.TargetExists=false;var e=new QuickCombat(o,750,false,null,"24","2",70);Step(e,o,0);o.Health=75;Check(Step(e,o,100).Action!=QuickAction.Food);o.Health=65;Check(Step(e,o,200).Action==QuickAction.Food);o.InCombat=o.Casting=true;Check(Step(e,o,300).Action==QuickAction.InterruptSkin);o.Casting=false;o.TargetExists=true;Step(e,o,400);Check(Step(e,o,500).Action==QuickAction.Face);});
        Test("a completed skin job cannot be rediscovered as a roadside corpse on a lagging frame",()=>{var o=Observation();o.LootKnown=true;o.Lootable=false;o.SkinKnown=o.Skinnable=o.SkinBindingKnown=o.SkinBindingCorrect=o.SkinSuccessKnown=o.CastEventsKnown=true;var e=new QuickCombat(o,750,true);Step(e,o,0);o.TargetDead=true;o.TargetCanAttack=false;Step(e,o,100);Step(e,o,200);Check(Step(e,o,700).Action==QuickAction.Skin);o.SkinSuccess=1;Step(e,o,2300);Check(e.Skins==1);for(long t=2400;t<4500;t+=100){var c=Step(e,o,t);Check(c.Action!=QuickAction.CorpseApproach&&c.Action!=QuickAction.CorpseSelect&&c.Action!=QuickAction.Loot&&c.Action!=QuickAction.Skin);}Check(e.Kills==1&&e.Skins==1);});
        Test("combat with failed casts detours around obstruction without stopping on the old deadline",()=>{var o=Observation();o.InCombat=o.CastEventsKnown=true;var e=new QuickCombat(o,750);Step(e,o,0);var back=Step(e,o,3500);Check(back.Action==QuickAction.BackOff&&back.CombatRecovery&&QuickCombat.Matches(back,o));var turn=Step(e,o,3800);Check(turn.Action==QuickAction.DetourTurn&&turn.CombatRecovery);o.Facing+=.5;var forward=Step(e,o,4200);Check(forward.Action==QuickAction.DetourForward&&forward.CombatRecovery&&QuickCombat.Matches(forward,o));o.CastSuccess++;Check(Step(e,o,4800).Action==QuickAction.Face);Check(Step(e,o,45000).Action!=QuickAction.Stop);o.TargetToken++;Check(!QuickCombat.Matches(forward,o));});
        Test("successful combat casts prevent false obstruction detours",()=>{var o=Observation();o.InCombat=o.CastEventsKnown=true;var e=new QuickCombat(o,750);Step(e,o,0);for(long t=500;t<50000;t+=500){o.CastSuccess++;var c=Step(e,o,t);Check(c.Action!=QuickAction.BackOff&&c.Action!=QuickAction.DetourTurn&&c.Action!=QuickAction.Stop);}});
        Test("low rogue energy waits for skills instead of repeatedly turning around",()=>{var o=Observation();o.InCombat=o.CastEventsKnown=true;o.PowerType=3;o.Power=20;var e=new QuickCombat(o,750);Step(e,o,0);for(long t=500;t<=10000;t+=500){var c=Step(e,o,t);Check(c.Action!=QuickAction.BackOff&&c.Action!=QuickAction.DetourTurn&&c.Action!=QuickAction.Stop);}o.Power=60;Check(Step(e,o,10500).Action==QuickAction.BackOff);});
        Test("confirmed melee contact does not turn away while auto attacks wait between skills",()=>{foreach(bool readableSwings in new[]{true,false}){var o=Observation();o.CastEventsKnown=true;var e=new QuickCombat(o,750,false,null,"","2");Step(e,o,0);o.InCombat=true;if(readableSwings){o.MeleeEventsKnown=true;o.MeleeHitToken=123;o.MeleeHits=1;}else{o.TargetVictimKnown=o.TargetTargetsPlayer=true;o.Health=99;}Step(e,o,100);for(int t=4000;t<=20000;t+=1000){var c=Step(e,o,t);Check(c.Action!=QuickAction.BackOff&&c.Action!=QuickAction.DetourTurn&&c.Action!=QuickAction.DetourForward);}}});
        Console.WriteLine("Quick combat tests: "+passed+" passed, "+failed+" failed. Fake observations only.");return failed==0?0:1;
    }
}
